    const m = /^(antigravity_pool_[a-z0-9]+)_(gemini|claude)$/.exec(String(item?.key || ''));
    if (m && !seenAgPools.has(m[1])) {
      seenAgPools.add(m[1]);
      const tag = extractAgPoolTag(item?.label);
      const poolLabel = tag ? `Antigravity · ${tag}` : 'Antigravity';
      dynamicAgPools.push({ id: m[1], label: poolLabel });
    }
  }
  // Server v0.8.1+ auto-splits Antigravity into full (antigravity_gemini/claude), optional
  // dynamic extra pools (antigravity_pool_*_gemini/claude), and lite (antigravity_lite_gemini/claude)
  // when accounts have different model pools, and unifies when all share one pool.
  const has4 = hasKey('antigravity_4_gemini') || hasKey('antigravity_4_claude');
  const has38 = hasKey('antigravity_3_8_gemini') || hasKey('antigravity_3_8_claude');
  const hasUnified = hasKey('antigravity_gemini') || hasKey('antigravity_claude');
  const hasLite = hasKey('antigravity_lite_gemini') || hasKey('antigravity_lite_claude');
  if (has4 || has38) {
    if (has4) gauges.push(antigravityGauge('antigravity_4', 'AGY (4)', 'antigravity_4', ag4, 'antigravity_4_gemini', 'antigravity_4_claude'));
    if (has38) gauges.push(antigravityGauge('antigravity_3_8', 'AGY (3.8)', 'antigravity_3_8', ag38, 'antigravity_3_8_gemini', 'antigravity_3_8_claude'));
    if (hasUnified) gauges.push(antigravityGauge('antigravity', 'Antigravity', 'antigravity', agLegacy.length ? agLegacy : ag, 'antigravity_gemini', 'antigravity_claude', { deriveLabel: true }));
    for (const pool of dynamicAgPools) {
      gauges.push(antigravityGauge(pool.id, pool.label, 'antigravity_full', agFull.length ? agFull : ag, `${pool.id}_gemini`, `${pool.id}_claude`, { deriveLabel: true }));
    }
    if (hasLite) gauges.push(antigravityGauge('antigravity_lite', 'Antigravity · Trial/Free', 'antigravity_lite', agLite.length ? agLite : ag, 'antigravity_lite_gemini', 'antigravity_lite_claude', { restricted: true, deriveLabel: true }));
  } else if (hasLite || dynamicAgPools.length > 0) {
    if (hasUnified) gauges.push(antigravityGauge('antigravity', 'Antigravity', 'antigravity_full', agFull.length ? agFull : ag, 'antigravity_gemini', 'antigravity_claude', { deriveLabel: true }));
    for (const pool of dynamicAgPools) {
      gauges.push(antigravityGauge(pool.id, pool.label, 'antigravity_full', agFull.length ? agFull : ag, `${pool.id}_gemini`, `${pool.id}_claude`, { deriveLabel: true }));
    }
    if (hasLite) gauges.push(antigravityGauge('antigravity_lite', 'Antigravity · Trial/Free', 'antigravity_lite', agLite.length ? agLite : ag, 'antigravity_lite_gemini', 'antigravity_lite_claude', { restricted: true, deriveLabel: true }));
  } else {
    gauges.push(antigravityGauge('antigravity', 'Antigravity', 'antigravity', ag, 'antigravity_gemini', 'antigravity_claude', { deriveLabel: true }));
  }
  return { label: t('title'), gauges };
}

function pollDelay(snapshot, settings = {}) {
  if (snapshot?.snapshot_complete === false || snapshot?.collection_in_progress === true) return 2000;
  const seconds = Number(settings.pollSeconds);
  if (Number.isFinite(seconds) && seconds > 0) return Math.min(900000, Math.max(10000, seconds * 1000));
  const hint = snapshot?.next_poll_hint_ms;
  return typeof hint === 'number' && Number.isFinite(hint) && hint > 0
    ? Math.min(900000, Math.max(10000, hint)) : 60000;
}

const isFiniteNumber = value => typeof value === 'number' && Number.isFinite(value);
const STICKY_TIER_IDS = ['antigravity_4', 'antigravity_3_8'];
const TIER_MISS_LIMIT = 3;
const GAUGE_ORDER = { claude: 0, gpt: 1, gemini: 2, antigravity_4: 3, antigravity_3_8: 4, antigravity: 5, antigravity_lite: 7 };
const gaugeOrder = id => {
  if (id in GAUGE_ORDER) return GAUGE_ORDER[id];
  if (String(id).startsWith('claude_pool_')) return 0;
  if (String(id).startsWith('codex_pool_')) return 1;
  if (String(id).startsWith('antigravity_pool_')) return 6;
  return 99;
};

// Keep the last known reading when a later snapshot returns null, and hold split Antigravity
// tier gauges (AGY 4 / AGY 3.8) across brief transient omissions so they do not flicker.
function mergeWithPrevious(previousGauges = [], nextGauges = [], missingCounts = {}) {
  const prevById = new Map((Array.isArray(previousGauges) ? previousGauges : []).map(g => [g.id, g]));
  const merged = (Array.isArray(nextGauges) ? nextGauges : []).map(next => {
    delete missingCounts[next.id];
    const prev = prevById.get(next.id);
    if (!prev) return next;
    const out = { ...next };
    const hasOuter = isFiniteNumber(out.remainingPercent) || isFiniteNumber(out.shortPercent) || isFiniteNumber(out.weeklyPercent);
    const prevOuter = isFiniteNumber(prev.remainingPercent) || isFiniteNumber(prev.shortPercent) || isFiniteNumber(prev.weeklyPercent);
    if (!hasOuter && prevOuter) {
      out.remainingPercent = prev.remainingPercent;
      if (isFiniteNumber(prev.shortPercent)) out.shortPercent = prev.shortPercent;
      if (isFiniteNumber(prev.weeklyPercent)) out.weeklyPercent = prev.weeklyPercent;
      out.rows = prev.rows;
      if (!out.accounts && prev.accounts) out.accounts = prev.accounts;
      if (!out.outerAccounts && prev.outerAccounts) out.outerAccounts = prev.outerAccounts;
      if (!out.updatedAt && prev.updatedAt) out.updatedAt = prev.updatedAt;
    }
    const hasInner = isFiniteNumber(out.innerRemainingPercent) || isFiniteNumber(out.innerShortPercent) || isFiniteNumber(out.innerWeeklyPercent);
    const prevInner = isFiniteNumber(prev.innerRemainingPercent) || isFiniteNumber(prev.innerShortPercent) || isFiniteNumber(prev.innerWeeklyPercent);
    if ('innerRemainingPercent' in out && !hasInner && prevInner) {
      out.innerRemainingPercent = prev.innerRemainingPercent;
      if (isFiniteNumber(prev.innerShortPercent)) out.innerShortPercent = prev.innerShortPercent;
      if (isFiniteNumber(prev.innerWeeklyPercent)) out.innerWeeklyPercent = prev.innerWeeklyPercent;
      out.innerRows = prev.innerRows;
      if (!out.innerAccounts && prev.innerAccounts) out.innerAccounts = prev.innerAccounts;
      if (!out.accounts && prev.accounts) out.accounts = prev.accounts;
      out.updatedAt = Math.max(out.updatedAt ?? 0, prev.updatedAt ?? 0) || null;
    }
    return out;
  });
  const nextIds = new Set(merged.map(g => g.id));
  const unifiedOnly = nextIds.has('antigravity') && !STICKY_TIER_IDS.some(id => nextIds.has(id));
  for (const id of STICKY_TIER_IDS) {
    if (nextIds.has(id) || unifiedOnly) {
      delete missingCounts[id];
      continue;
    }
    const prev = prevById.get(id);
    if (!prev) {
      delete missingCounts[id];
      continue;
    }
    const misses = (missingCounts[id] || 0) + 1;
    if (misses < TIER_MISS_LIMIT) {
      missingCounts[id] = misses;
      merged.push(prev);
    } else {
      delete missingCounts[id];
    }
  }
  merged.sort((a, b) => gaugeOrder(a.id) - gaugeOrder(b.id));
  return merged;
}

// What the worker hands to components/Gauge.svelte (plain data); the component draws it in the app.
// Rings and popovers show only the upstream overall remaining quota.



// Low remaining overrides the brand color so a nearly exhausted limit stands out.
function tone(value, color) {
  if (value === null || value === undefined) return color;
  return value <= 5 ? 'danger' : value <= 20 ? 'warn' : color;
}

function rows(list, color, group, groupAccounts = null) {
  const items = list || [];
  const hasWindowRows = items.some(row => Boolean(row.window));
  const groupName = group && hasWindowRows && items[0]?.tier ? `${group} · ${items[0].tier}` : group;
  return items.map((row, index) => {
    if (row.window) {
      const out = { label: row.label, value: row.value, color: tone(row.value, color), window: row.window };
      if (groupName) out.group = groupName;
      if (index === 0 && Number.isInteger(groupAccounts) && groupAccounts > 0) out.groupAccounts = groupAccounts;
      return out;
    }
    const isGroupHead = Boolean(groupName && index === 0);
    const label = isGroupHead
      ? (row.tier ? `${groupName} · ${row.tier}` : groupName)
      : row.label;
    const out = { label, value: row.value, color: tone(row.value, color) };
    if (groupName) out.group = groupName;
    if (index === 0 && Number.isInteger(groupAccounts) && groupAccounts > 0) out.groupAccounts = groupAccounts;
    if (isGroupHead || row.summary) out.summary = true;
    return out;
  });
}

function gaugeData(gauge, error, fetchedAt = null) {
  const isAntigravity = gauge.brand === 'antigravity' || gauge.brand === 'antigravity_full' || gauge.brand === 'antigravity_lite' || gauge.brand === 'antigravity_4' || gauge.brand === 'antigravity_3_8';
  const outerColor = gauge.brand === 'antigravity' ? COLORS.gemini : COLORS[gauge.brand];
  const ring = (value, color, label, shortVal = null, weeklyVal = null) => {
    const out = { value, color: tone(value, color), label };
    if (shortVal !== null && weeklyVal !== null) {
      out.short = shortVal;
      out.shortColor = tone(shortVal, color);
      out.weekly = weeklyVal;
      out.weeklyColor = tone(weeklyVal, color);
    }
    return out;
  };
  const isPrimaryAg = gauge.brand === 'antigravity' || gauge.brand === 'antigravity_full';
  const outerRingLabel = isPrimaryAg
    ? t('remainingOf', { name: 'Gemini' })
    : t('remainingOf', { name: `${gauge.label} · Gemini` });
  const innerRingLabel = isPrimaryAg
    ? t('remainingOf', { name: 'Claude via Antigravity' })
    : t('remainingOf', { name: `${gauge.label} · Claude/GPT` });
  const rings = isAntigravity
    ? [
        ring(gauge.remainingPercent, outerColor, outerRingLabel, gauge.shortPercent ?? null, gauge.weeklyPercent ?? null),
        ring(gauge.innerRemainingPercent ?? null, COLORS.claude, innerRingLabel, gauge.innerShortPercent ?? null, gauge.innerWeeklyPercent ?? null)
      ]
    : [ring(gauge.remainingPercent, COLORS[gauge.brand], t('remainingOf', { name: gauge.label }), gauge.shortPercent ?? null, gauge.weeklyPercent ?? null)];
  const showGroupAccounts = isAntigravity
    && Number.isInteger(gauge.outerAccounts) && gauge.outerAccounts > 0
    && Number.isInteger(gauge.innerAccounts) && gauge.innerAccounts > 0
    && gauge.outerAccounts !== gauge.innerAccounts;
  let detailRows = isAntigravity
    ? [
        ...rows(gauge.rows, outerColor, 'Gemini', showGroupAccounts ? gauge.outerAccounts : null),
        ...rows(gauge.innerRows, COLORS.claude, 'Claude/GPT', showGroupAccounts ? gauge.innerAccounts : null)
      ]
    : rows(gauge.rows, COLORS[gauge.brand]);
  if (!detailRows.length) detailRows = [{ label: t('noQuotaInfo'), value: null }];
  const titleName = !isAntigravity && gauge.singleTier && !gauge.label.includes(' · ') ? `${gauge.label} · ${gauge.singleTier}` : gauge.label;
  const title = t('remainingOf', { name: titleName });
  const details = { title: title.slice(0, 64), rows: detailRows.slice(0, 20) };
  if (Number.isInteger(gauge.accounts) && gauge.accounts > 0) details.accounts = gauge.accounts;
  const node = {
    id: gauge.id, label: gauge.label, rings,
    icon: LOGOS[gauge.brand],
    hint: [gauge.hint, error].filter(Boolean).join(' · ').slice(0, 500),
    details
  };
  // The monitor's own observation time wins; otherwise the last successful read. A failed read never advances either.
  const updatedAt = Number.isFinite(gauge.updatedAt) && gauge.updatedAt > 0 ? gauge.updatedAt : fetchedAt;
  if (Number.isFinite(updatedAt) && updatedAt > 0) node.details.updatedAt = Math.round(updatedAt);
  // Show the last known value cleanly without a warning badge; flag stale only when no value is known.
  const hasValue = rings.some(r => typeof r.value === 'number' && Number.isFinite(r.value));
  if (!hasValue && (gauge.stale || error || fetchedAt !== null)) node.stale = true;
  return node;
}

function gaugesData(model, error) {
  return model.gauges.map(gauge => gaugeData(gauge, error, model.fetchedAt));
}

// Text the component needs, already in the extension's language (the component never translates).
function strings() {
  return Object.fromEntries(['unknown', 'stale', 'shortWindow', 'weeklyWindow', 'accountCountOne', 'accountCount', 'updated', 'sec', 'min', 'hour', 'day'].map(key => [key, t(key)]));
}

// Async SDK function body; model.mjs is prepended by scripts/build.mjs.
// The worker only polls and shapes data; the gauges are drawn by components/Gauge.svelte (mounted in the header).
const initialSettings = await sdk.settings.get();
// 'auto' follows the language the app shows (Settings > General), not the browser's; it is read again on a switch.
let appLanguage = '';
async function readAppLanguage() {
  try { appLanguage = String((await sdk.context.get())?.language ?? ''); } catch { /* keep the last one */ }
}
const languages = () => (appLanguage ? [appLanguage] : undefined);
await readAppLanguage();
setLanguage(initialSettings?.language, languages());
// Quota data is served only on the authenticated management route (/v0/resource is unauthenticated
// and carries no data). The host adds `Authorization: Bearer <httpToken>` from this extension's own
// settings; the extension never sees the token on the wire and cannot choose another origin/header.
const QUOTA_PATH = '/v0/management/plugins/quota-monitor/data/accounts';
// CLIProxyAPI bans an IP for 30 minutes after five rejected management requests, so a missing or
// rejected key is never retried: requests resume only once the stored key itself changes.
let rejectedKey = null;
const keyOf = value => (typeof value?.httpToken === 'string' ? value.httpToken.trim() : '');
let settings = initialSettings;
let model = {
  label: t('title'),
  gauges: [
    { id: 'claude', label: 'Claude', brand: 'claude', remainingPercent: null },
    { id: 'antigravity', label: 'Antigravity', brand: 'antigravity', remainingPercent: null }
  ]
};
let pending = null;
let timer;
let lastAttempt = 0;
let failures = 0;
let followUp = false;
const missingTierCounts = {};

function render(error) {
  return sdk.components.setData({ label: t('itemLabel'), gauges: gaugesData(model, error), strings: strings() });
}

function schedule(delay) {
  clearTimeout(timer);
  timer = setTimeout(() => { void refresh(); }, delay);
}

function refresh() {
  if (pending) return pending;
  // Run-finished events and timers cannot create a request burst.
  if (Date.now() - lastAttempt < 2000) {
    schedule(2000);
    return Promise.resolve();
  }
  lastAttempt = Date.now();
  pending = (async () => {
    let delay = 60000;
    try {
      // Re-read the (local, free) settings so a corrected key or interval applies without a reload.
      settings = await sdk.settings.get();
      setLanguage(settings?.language, languages());
      const key = keyOf(settings);
      if (!key) throw Object.assign(new Error(t('needKey')), { authBlocked: true });
      if (key === rejectedKey) throw Object.assign(new Error(t('badKey')), { authBlocked: true });
      const response = await sdk.http.requestJson({ path: QUOTA_PATH });
      if (response.status === 401 || response.status === 403) {
        rejectedKey = key;
        throw Object.assign(new Error(t('badKey')), { authBlocked: true });
      }
      if (response.status < 200 || response.status >= 300) throw new Error(t('serverError', { status: response.status }));
      const snapshot = response.body;
      delay = pollDelay(snapshot, settings);
      model = { ...gaugesFromSnapshot(snapshot), fetchedAt: Date.now() };
      await render();
      failures = 0;
    } catch (error) {
      failures += 1;
      const text = String(error?.message || t('cannotRead')).slice(0, 200);
      model = { ...model, gauges: model.gauges.map(gauge => ({ ...gauge, stale: true })) };
      await render(text);
      // Keep last-good values. Never turn failed, unconfigured or missing data into 0%.
      // Auth problems cost nothing locally, so re-check the settings every 15 s; never hit the server.
      delay = error?.authBlocked ? 15000 : error?.code === 'waiting' ? 2000 : Math.min(300000, 10000 * 2 ** Math.min(failures - 1, 5));
    } finally {
      pending = null;
      schedule(followUp ? Math.min(delay, 2500) : delay);
      followUp = false;
    }
  })().catch(() => { /* Host teardown stops the worker and all timers. */ });
  return pending;
}

await render();
await sdk.events.on(event => {
  if (event.type === 'language_changed') {
    // Redraw at once in the new language; no request is needed for that.
    void readAppLanguage().then(() => { setLanguage(settings?.language, languages()); return render(); }).catch(() => {});
    return;
  }
  if (event.type === 'run_finished') {
    if (pending) followUp = true;
    else schedule(2500);
  }
});
// Do not wait for the network during the host's 5-second extension startup deadline.
void refresh();
